    test('resolveThread warns and no-ops without threadId', function () {
        var calls = [];
        var scm = makeAdo({
            ado_resolve_pr_thread: function (args) { calls.push(args); return 'resolved'; }
        });
        assert.equal(scm.resolveThread(5, {}), undefined);
        assert.deepEqual(calls, []);
