        var scm2 = makeAdo({
            ado_list_prs: function () { return [{ id: 3 }]; }
        });
        assert.deepEqual(scm2.listPrs('open'), [{ id: 3 }]);
        var scm3 = makeAdo({
            ado_list_prs: function () { return '[{"id":4}]'; }
        });
        assert.deepEqual(scm3.listPrs('open'), [{ id: 4 }]);
        var scm4 = makeAdo({
            ado_list_prs: function () { return { count: 0 }; }
