                return JSON.stringify({ count: 2, value: [{ id: 1 }, { id: 2 }] });
            }
        });
        var prs = scm.listPrs('open');
        assert.deepEqual(calls, [{ repository: 'my-repo', status: 'active' }]);
        assert.deepEqual(prs, [{ id: 1 }, { id: 2 }]);
