        assert.deepEqual(scm3.listPrs('open'), [{ id: 4 }]);
        var scm4 = makeAdo({
            ado_list_prs: function () { return { count: 0 }; }
        });
        assert.deepEqual(scm4.listPrs('open'), { count: 0 });
    });

    test('getPr parses the JSON envelope and stringifies the PR id', function () {
        var calls = [];
