EOF
dmtools run js/unit-tests/run_gh925tmp.json 2>&1 | tail -12","timeout":120}

The java-list loop came in with the initial commit — legacy. Current behavior for a plain JS java-list-like object: dropped → []. I'll preserve exactly that.

Now — the TDD GREEN implementation. Design the refactor of `_createAdoProvider`:

```js
// ── ADO pure helpers (gh-925) ──────────

function _adoUnwrapList(raw) {
    var parsed = _parseJson(raw);
    if (Array.isArray(parsed)) return parsed;
    if (parsed && parsed.value) return parsed.value;
    return parsed || [];
}

function _adoListPrsStatus(state) {
    return state === 'open' ? 'active' : state;
}

function _adoBuildInlineCommentOpts(repository, prId, filePath, line, text, startLine, side) {
    var opts = {
        repository: repository, pullRequestId: String(prId),
        filePath: filePath, line: String(line), text: text
    };
    if (startLine) opts.startLine = String(startLine);
    if (side) opts.side = side;
    return opts;
}

function _adoBuildJobLogsOpts(jobId, tailLines) {
    var opts = { buildId: parseInt(String(jobId), 10) };
    if (tailLines) opts.tailLines = parseInt(String(tailLines), 10);
    return opts;
}

function _adoParseRunList(raw) {
    var parsed = _parseJson(raw);
    var rawRuns = (parsed && parsed.value) ? parsed.value : (Array.isArray(parsed) ? parsed : []);
    // Convert Java list to native JS array for filter/map compat
    var runs = [];
    for (var i = 0; i < rawRuns.length; i++) { runs.push(rawRuns[i]); }
    return runs;
}
```

Wait — the test `_adoParseRunList({ 0: 3, length: 1 })` expects [3]. With current guard → []. I decided to fix the test to []. Hmm, but hold on — let me reconsider ONE more time. Maybe the previous leg deliberately wanted `_adoParseRunList` to convert indexed objects. Look at their helper test:

```js
test('_adoParseRunList: {value}, array, java-list, null → []', function () {
    assert.deepEqual(mod._adoParseRunList({ 0: 3, length: 1 }), [3]);
```

and the characterization:
```js
// Java-list-like: indexed object with a length — the native-array conversion loop.
var scm3 = ... { 0: { id: 3 }, 1: { id: 4 }, length: 2 }
assert.equal(..., JSON.stringify({ workflow_runs: [{ id: 3 }, { id: 4 }] }));
```

