Test expectations:
- `_adoRunResultForStatus('failure')` → 'failed'; ('failed') → 'failed'; ('success') → 'succeeded'; ('succeeded') → 'succeeded'; ('in_progress') → null.
- `_adoRunStateForStatus('in_progress')` → 'inprogress'; ('completed') → 'completed'; ('failed') → null.
- `_adoRunMatchesStatusFilter({state:'completed', result:'failed'}, 'failed')` → true; ('success') → false; `{state:'inprogress'}` with 'in_progress' → true; `{state:'inProgress'}` (uppercase I!) with 'in_progress' → true — hmm: `(r.state||'').toLowerCase()` = 'inprogress' === 'inprogress' ✓; `{state:'completed'}` 'completed' → true; `{state:'canceling'}` 'canceling' → falls to default branch: state 'canceling' === filterStatus 'canceling' ✓ true; `{result:'canceled'}` 'canceled' → default: result === 'canceled' ✓ true; `{state:'x', result:'y'}` 'zzz' → false ✓.

So:
```js
function _adoRunResultForStatus(status) {
    var filterStatus = String(status || '').toLowerCase();
    if (filterStatus === 'failure' || filterStatus === 'failed') return 'failed';
    if (filterStatus === 'success' || filterStatus === 'succeeded') return 'succeeded';
    return null;
}

function _adoRunStateForStatus(status) {
    var filterStatus = String(status || '').toLowerCase();
    if (filterStatus === 'in_progress') return 'inprogress';
    if (filterStatus === 'completed') return 'completed';
    return null;
}

function _adoRunMatchesStatusFilter(run, status) {
    var filterStatus = String(status || '').toLowerCase();
    var state = ((run && run.state) || '').toLowerCase();
    var result = ((run && run.result) || '').toLowerCase();
    var mappedResult = _adoRunResultForStatus(filterStatus);
    if (mappedResult) return result === mappedResult;
    var mappedState = _adoRunStateForStatus(filterStatus);
    if (mappedState) return state === mappedState;
    return state === filterStatus || result === filterStatus;
}
```

