// ── GitLab discussion helpers (gh-925) ──────────
// Pure mappers/renders extracted from _createGitLabProvider().fetchDiscussions
// — behaviour-preserving, pinned by test_scmGitlabDiscussions.js.

function _gitlabMapDiscussionThread(thread, index) {
    var notes = thread.notes || [];
    var root = notes[0] || {};
    var pos = root.position || {};
    return {
        index: index,
        rootCommentId: thread.id,
        threadId: thread.id,
        discussionId: thread.id,
        path: pos.new_path || pos.old_path || null,
        line: pos.new_line || pos.old_line || null,
        resolved: thread.resolved === true || root.resolved === true,
        body: (root.body || '').trim()
    };
}

function _gitlabThreadAuthor(author) {
    return author ? (author.username || author.name) : 'unknown';
}

function _gitlabThreadDate(comment) {
    return (comment && comment.created_at) ? comment.created_at.substring(0, 10) : '';
}

function _gitlabRenderThreadSection(mapped, notes) {
    var section = '### Thread ' + mapped.index;
    if (mapped.path) {
        section += ' — `' + mapped.path + '`';
        if (mapped.line) section += ' line ' + mapped.line;
    }
    section += '\n';
    var root = notes[0] || {};
    section += mapped.body
        ? ('**' + _gitlabThreadAuthor(root.author) + '** (' + _gitlabThreadDate(root) + '):\n' + mapped.body + '\n')
        : '_[No comment body]_\n';
    for (var i = 1; i < notes.length; i++) {
        var reply = notes[i] || {};
        section += '> **' + _gitlabThreadAuthor(reply.author) + '** (' + _gitlabThreadDate(reply) + '): ' + (reply.body || '').trim() + '\n';
    }
    section += '---\n';
    return section;
}

function _gitlabFetchDiscussions(workspace, repository, prId) {
    var discussions = _toArray(gitlab_get_mr_discussions({
        workspace: workspace, repository: repository, pullRequestId: String(prId)
    }));
    var sections = [];
    var rawThreads = [];
    var section = '## Review Threads\n';
    var hasContent = false;

    discussions.forEach(function(thread) {
        var mapped = _gitlabMapDiscussionThread(thread, rawThreads.length + 1);
        rawThreads.push(mapped);
        if (mapped.resolved) return;
        hasContent = true;
        section += _gitlabRenderThreadSection(mapped, thread.notes || []);
    });

    if (hasContent) sections.push(section);
    return {
        markdown: sections.length > 0
            ? '# PR Discussion History\n_Previous review discussions for MR #' + prId + '._\n' + sections.join('\n')
            : null,
        rawThreads: rawThreads.length > 0 ? { threads: rawThreads } : null
    };
}
