        assert.equal(
            mod._gitlabRenderThreadSection({ index: 1, path: '/a.js', line: null, body: 'fix it' }, [root]),
            '### Thread 1 — `/a.js`\n\n**dev** (2026-01-02):\nfix it\n---\n\n');
